#!/usr/bin/env bun
/**
 * Replay History - Comprehensive historical import
 *
 * Replays complete Claude Code sessions into claude-mem database:
 * - Session records with historical timestamps
 * - User prompts (all messages you sent)
 * - Observations from tool usage (generated by SDK)
 * - Session summaries
 * - Chroma vector embeddings (for semantic search)
 *
 * Usage:
 *   bun src/bin/replay-history.ts <project-dir>
 *   bun src/bin/replay-history.ts --all
 *   bun src/bin/replay-history.ts --all --dry-run
 *   bun src/bin/replay-history.ts --all --no-chroma
 *   bun src/bin/replay-history.ts --session <session-id> <project-dir>
 */

// MUST be imported first - fixes Agent SDK env var conflicts
import '../utils/agent-sdk-env-fix.js';

import { readFileSync, readdirSync, existsSync } from 'fs';
import { join, basename } from 'path';
import { homedir } from 'os';
import { SessionStore } from '../services/sqlite/SessionStore.js';
import { ChromaSync } from '../services/sync/ChromaSync.js';
import { parseObservations, parseSummary } from '../sdk/parser.js';
import { buildInitPrompt, buildObservationPrompt, buildSummaryPrompt } from '../sdk/prompts.js';
// @ts-ignore
import { query } from '@anthropic-ai/claude-agent-sdk';
import { execSync } from 'child_process';
import { SettingsDefaultsManager } from '../shared/SettingsDefaultsManager.js';
import { USER_SETTINGS_PATH } from '../shared/paths.js';

interface TranscriptEvent {
  timestamp: string;
  sessionId: string;
  cwd: string;
  message: {
    role: string;
    content: any;
  };
}

interface UserMessage {
  timestamp: Date;
  promptNumber: number;
  text: string;
}

interface ToolEvent {
  timestamp: Date;
  toolName: string;
  toolInput: any;
  toolResponse: any;
  toolUseId: string;
  promptNumber?: number;  // Track which user prompt this tool belongs to
}

interface SessionData {
  sessionId: string;
  project: string;
  startTime: Date;
  userMessages: UserMessage[];
  toolEvents: ToolEvent[];
  allMessages: TranscriptEvent[];
  assistantResponses: string[];  // Collect assistant text for summary context
}

/**
 * Parse a single transcript file and extract events
 */
function parseTranscript(filepath: string): TranscriptEvent[] {
  const events: TranscriptEvent[] = [];
  const content = readFileSync(filepath, 'utf-8');
  const lines = content.split('\n').filter(l => l.trim());

  for (const line of lines) {
    try {
      const data = JSON.parse(line);
      if (data.timestamp && data.sessionId && data.message) {
        events.push({
          timestamp: data.timestamp,
          sessionId: data.sessionId,
          cwd: data.cwd || '',
          message: data.message
        });
      }
    } catch (e) {
      // Skip invalid lines
    }
  }

  return events;
}

/**
 * Group events by session and extract structured data
 */
function groupBySession(events: TranscriptEvent[]): Map<string, SessionData> {
  const sessions = new Map<string, SessionData>();

  // First pass: identify sessions and basic metadata
  for (const event of events) {
    const sessionId = event.sessionId;

    if (!sessions.has(sessionId)) {
      // Extract project name from full path (e.g., "cost-analysis" from "/Users/.../cost-analysis")
      const projectName = event.cwd ? basename(event.cwd) : 'unknown';

      sessions.set(sessionId, {
        sessionId,
        project: projectName,
        startTime: new Date(event.timestamp),
        userMessages: [],
        toolEvents: [],
        allMessages: [],
        assistantResponses: []
      });
    }

    sessions.get(sessionId)!.allMessages.push(event);
  }

  // Second pass: extract user messages and tool events with proper attribution
  for (const [sessionId, session] of sessions) {
    let promptNumber = 1;
    const toolUseMap = new Map<string, { toolName: string; toolInput: any; timestamp: Date }>();

    // Track the current prompt number for tool attribution
    let currentPromptForTools = 1;

    for (const event of session.allMessages) {
      const role = event.message.role;
      const content = event.message.content;

      // Extract user text messages
      if (role === 'user') {
        // Check if this is a tool_result message (not a new user prompt)
        const isToolResult = Array.isArray(content) && content.some((b: any) => b.type === 'tool_result');

        if (!isToolResult) {
          // This is a real user message - handle both formats
          // Handle string content (older transcript format)
          if (typeof content === 'string' && content.trim()) {
            const text = content.trim();
            // Filter out system messages, interrupts, and bash notifications
            if (!text.startsWith('[Request interrupted') &&
                !text.startsWith('Caveat: The messages below') &&
                !text.startsWith('<bash-input>') &&
                !text.startsWith('<bash-stdout>') &&
                !text.startsWith('<bash-stderr>')) {
              session.userMessages.push({
                timestamp: new Date(event.timestamp),
                promptNumber: promptNumber,
                text
              });
              currentPromptForTools = promptNumber;  // Tools after this belong to this prompt
              promptNumber++;
            }
          }
          // Handle array content (current transcript format)
          else if (Array.isArray(content)) {
            for (const block of content) {
              if (block.type === 'text' && block.text && block.text.trim()) {
                // Filter out system messages, interrupts, and bash notifications
                const text = block.text.trim();
                if (!text.startsWith('[Request interrupted') &&
                    !text.startsWith('Caveat: The messages below') &&
                    !text.startsWith('<bash-input>') &&
                    !text.startsWith('<bash-stdout>') &&
                    !text.startsWith('<bash-stderr>')) {
                  session.userMessages.push({
                    timestamp: new Date(event.timestamp),
                    promptNumber: promptNumber,
                    text
                  });
                  currentPromptForTools = promptNumber;  // Tools after this belong to this prompt
                  promptNumber++;
                }
              }
            }
          }
        }
      }

      // Extract tool_use and text from assistant messages
      if (role === 'assistant' && Array.isArray(content)) {
        for (const block of content) {
          // Capture tool_use events
          if (block.type === 'tool_use' && block.id && block.name && block.input) {
            toolUseMap.set(block.id, {
              toolName: block.name,
              toolInput: block.input,
              timestamp: new Date(event.timestamp)
            });
          }
          // Capture assistant text responses for summary context
          if (block.type === 'text' && block.text) {
            session.assistantResponses.push(block.text);
          }
        }
      }

      // Match tool_result with tool_use
      if (role === 'user' && Array.isArray(content)) {
        for (const block of content) {
          if (block.type === 'tool_result' && block.tool_use_id) {
            const toolUse = toolUseMap.get(block.tool_use_id);
            if (toolUse) {
              // Assign this tool to the current prompt (last user message seen)
              session.toolEvents.push({
                timestamp: toolUse.timestamp,
                toolName: toolUse.toolName,
                toolInput: toolUse.toolInput,
                toolResponse: block.content,
                toolUseId: block.tool_use_id,
                promptNumber: currentPromptForTools
              });
              toolUseMap.delete(block.tool_use_id);
            }
          }
        }
      }
    }
  }

  return sessions;
}

/**
 * Find Claude executable
 */
function findClaudeExecutable(): string {
  const settings = SettingsDefaultsManager.loadFromFile(USER_SETTINGS_PATH);

  if (settings.CLAUDE_CODE_PATH) {
    return settings.CLAUDE_CODE_PATH;
  }

  try {
    return execSync('which claude', { encoding: 'utf-8' }).trim();
  } catch {
    throw new Error('Claude executable not found. Set CLAUDE_CODE_PATH in settings.');
  }
}

/**
 * Generate observations for ALL tool events using single persistent SDK session
 * Matches real claude-mem PostToolUse behavior:
 * - ONE SDK session for entire replay (not batched)
 * - Tools streamed individually to SDK via message generator
 * - SDK decides natural observation grouping with full context
 * - Prompt numbers preserved from tool events for correct attribution
 */
async function generateObservations(
  toolEvents: ToolEvent[],
  userMessage: string,
  project: string,
  sessionId: string,
  modelId: string,
  claudePath: string
): Promise<any[]> {
  if (toolEvents.length === 0) return [];

  const disallowedTools = ['Bash', 'Read', 'Write', 'Edit', 'Grep', 'Glob', 'WebFetch', 'WebSearch', 'Task', 'NotebookEdit', 'AskUserQuestion', 'TodoWrite'];

  // Create message generator that yields init prompt + tool events
  async function* messageGenerator() {
    // First message: init prompt
    yield {
      type: 'user' as const,
      message: {
        role: 'user' as const,
        content: buildInitPrompt(project, sessionId, userMessage)
      }
    };

    // Then yield each tool event
    for (const event of toolEvents) {
      const epoch = event.timestamp instanceof Date && !isNaN(event.timestamp.getTime())
        ? event.timestamp.getTime()
        : Date.now();

      yield {
        type: 'user' as const,
        message: {
          role: 'user' as const,
          content: buildObservationPrompt({
            id: 0,
            tool_name: event.toolName,
            tool_input: typeof event.toolInput === 'string' ? event.toolInput : JSON.stringify(event.toolInput),
            tool_output: typeof event.toolResponse === 'string' ? event.toolResponse : JSON.stringify(event.toolResponse),
            created_at_epoch: epoch,
            cwd: project
          })
        }
      };
    }
  }

  // Query SDK with message generator
  const messages: any[] = [];
  const queryResult = query({
    prompt: messageGenerator(),
    options: {
      model: modelId,
      disallowedTools,
      pathToClaudeCodeExecutable: claudePath,
      max_tokens: 8192
    }
  });

  for await (const message of queryResult) {
    if (message.type === 'assistant') {
      messages.push(message);
    }
  }

  // Parse observations from SDK responses
  console.log(`    SDK returned ${messages.length} messages`);
  const observations: any[] = [];
  for (const message of messages) {
    const content = message.message.content;
    const textContent = Array.isArray(content)
      ? content.filter((c: any) => c.type === 'text').map((c: any) => c.text).join('\n')
      : typeof content === 'string' ? content : '';

    console.log(`    Message text length: ${textContent.length} chars`);
    if (textContent.length > 0) {
      console.log(`    First 500 chars: ${textContent.substring(0, 500)}`);
    }

    if (textContent) {
      const parsed = parseObservations(textContent);
      console.log(`    Parsed ${parsed.length} observations from this message`);
      observations.push(...parsed);
    }
  }
  console.log(`    Total observations parsed: ${observations.length}`);

  return observations;
}

/**
 * Generate session summary using SDK
 */
async function generateSummary(
  sessionData: SessionData,
  modelId: string,
  claudePath: string
): Promise<any | null> {
  // Build session object matching current SDKSession interface
  // Concatenate last 5000 characters of assistant responses for context
  const assistantContext = sessionData.assistantResponses.join('\n').slice(-5000);

  const session = {
    id: 0, // Not used in prompt
    sdk_session_id: sessionData.sessionId,  // Use original session ID
    project: sessionData.project,
    user_prompt: sessionData.userMessages[0]?.text || '',
    last_user_message: sessionData.userMessages[sessionData.userMessages.length - 1]?.text || '',
    last_assistant_message: assistantContext || 'No assistant responses captured'
  };

  // Use current buildSummaryPrompt API (single session parameter)
  const prompt = buildSummaryPrompt(session);

  const disallowedTools = ['Bash', 'Read', 'Write', 'Edit', 'Grep', 'Glob', 'WebFetch', 'WebSearch', 'Task', 'NotebookEdit', 'AskUserQuestion', 'TodoWrite'];

  const messages: any[] = [];
  const queryResult = query({
    prompt,
    options: {
      model: modelId,
      disallowedTools,
      pathToClaudeCodeExecutable: claudePath
    }
  });

  for await (const message of queryResult) {
    if (message.type === 'assistant') {
      messages.push(message);
    }
  }

  // Parse summary from SDK response
  for (const message of messages) {
    const content = message.message.content;
    const textContent = Array.isArray(content)
      ? content.filter((c: any) => c.type === 'text').map((c: any) => c.text).join('\n')
      : typeof content === 'string' ? content : '';

    if (textContent) {
      const parsed = parseSummary(textContent);
      if (parsed) return parsed;
    }
  }

  return null;
}

/**
 * Replay a single session into database
 */
async function replaySession(
  sessionData: SessionData,
  db: SessionStore,
  modelId: string,
  claudePath: string,
  dryRun: boolean,
  syncToChroma: boolean = true
): Promise<{ prompts: number; observations: number; summary: boolean }> {
  const stats = { prompts: 0, observations: 0, summary: false };

  if (dryRun) {
    console.log(`  [DRY RUN] Would replay:`);
    console.log(`    - ${sessionData.userMessages.length} user messages`);
    console.log(`    - ${sessionData.toolEvents.length} tool events`);
    return stats;
  }

  // Use original session ID unchanged - matches system contract
  // Normal sessions have claude_session_id === sdk_session_id (no prefix)
  const sessionId = sessionData.sessionId;

  // Initialize Chroma sync (all projects use 'claude-mem' collection)
  const chromaSync = syncToChroma ? new ChromaSync('claude-mem') : null;

  // Check if session already exists
  const existing = db['db'].prepare('SELECT id FROM sdk_sessions WHERE claude_session_id = ?')
    .get(sessionId) as { id: number } | undefined;

  if (existing) {
    console.log(`  ⊘ Session already imported, skipping`);
    return stats;
  }

  // Create session record
  const sessionDbId = db.createSDKSession(
    sessionId,
    sessionData.project,
    sessionData.userMessages[0]?.text || ''
  );
  db.updateSDKSessionId(sessionDbId, sessionId);

  console.log(`  ✓ Created session record`);

  // Store user prompts with historical timestamps
  for (const userMsg of sessionData.userMessages) {
    db.saveHistoricalUserPrompt(
      sessionData.sessionId,
      userMsg.promptNumber,
      userMsg.text,
      userMsg.timestamp
    );
    stats.prompts++;
  }

  console.log(`  ✓ Stored ${stats.prompts} user prompts`);

  // Generate and store observations from tool events
  // Smart chunking: sessions >150 tools split into chunks to prevent SDK context exhaustion
  if (sessionData.toolEvents.length > 0) {
    const MAX_TOOLS_PER_CHUNK = 150;
    const totalTools = sessionData.toolEvents.length;

    if (totalTools > MAX_TOOLS_PER_CHUNK) {
      // Large session: split into chunks
      const numChunks = Math.ceil(totalTools / MAX_TOOLS_PER_CHUNK);
      console.log(`  ⏳ Generating observations from ${totalTools} tool events using smart chunking (${numChunks} chunks of max ${MAX_TOOLS_PER_CHUNK} tools)...`);

      for (let chunkIdx = 0; chunkIdx < numChunks; chunkIdx++) {
        const startIdx = chunkIdx * MAX_TOOLS_PER_CHUNK;
        const endIdx = Math.min(startIdx + MAX_TOOLS_PER_CHUNK, totalTools);
        const chunkTools = sessionData.toolEvents.slice(startIdx, endIdx);

        console.log(`    Processing chunk ${chunkIdx + 1}/${numChunks} (tools ${startIdx + 1}-${endIdx})...`);

        try {
          const observations = await generateObservations(
            chunkTools,
            sessionData.userMessages[0]?.text || '',
            sessionData.project,
            sessionId,
            modelId,
            claudePath
          );

          console.log(`      SDK generated ${observations.length} observations for this chunk`);

          // Store observations with correct attribution
          for (let i = 0; i < observations.length; i++) {
            const obs = observations[i];
            const toolIdx = Math.min(startIdx + i, totalTools - 1);
            const tool = sessionData.toolEvents[toolIdx];
            const timestamp = tool.timestamp;
            const promptNum = tool.promptNumber || 1;

            const result = db.storeHistoricalObservation(
              sessionId,
              sessionData.project,
              obs,
              timestamp,
              promptNum,
              0
            );

            if (chromaSync) {
              try {
                await chromaSync.syncObservation(
                  result.id,
                  sessionId,
                  sessionData.project,
                  obs,
                  promptNum,
                  result.createdAtEpoch,
                  0
                );
              } catch (error: any) {
                console.error(`        ⚠️  Chroma sync failed for observation #${result.id}: ${error.message}`);
              }
            }

            stats.observations++;
          }
        } catch (error: any) {
          console.error(`      ❌ Chunk ${chunkIdx + 1} failed:`, error.message);
        }
      }

      console.log(`  ✓ Generated and stored ${stats.observations} observations across ${numChunks} chunks`);
    } else {
      // Small session: single persistent SDK session (matches real claude-mem behavior)
      console.log(`  ⏳ Generating observations from ${totalTools} tool events using single persistent SDK session...`);

      try {
        const observations = await generateObservations(
          sessionData.toolEvents,
          sessionData.userMessages[0]?.text || '',
          sessionData.project,
          sessionId,
          modelId,
          claudePath
        );

        console.log(`    SDK generated ${observations.length} observations`);

        // Store observations with correct prompt number attribution
        let toolIndex = 0;
        for (const obs of observations) {
          const tool = sessionData.toolEvents[toolIndex] || sessionData.toolEvents[0];
          const timestamp = tool.timestamp;
          const promptNum = tool.promptNumber || 1;

          const result = db.storeHistoricalObservation(
            sessionId,
            sessionData.project,
            obs,
            timestamp,
            promptNum,
            0
          );

          if (chromaSync) {
            try {
              await chromaSync.syncObservation(
                result.id,
                sessionId,
                sessionData.project,
                obs,
                promptNum,
                result.createdAtEpoch,
                0
              );
            } catch (error: any) {
              console.error(`      ⚠️  Chroma sync failed for observation #${result.id}: ${error.message}`);
            }
          }

          stats.observations++;
          toolIndex++;
        }

        console.log(`  ✓ Generated and stored ${stats.observations} observations`);
      } catch (error: any) {
        console.error(`    ❌ Failed to generate observations:`, error.message);
      }
    }
  }

  // Generate and store session summary
  if (sessionData.userMessages.length > 0) {
    console.log(`  ⏳ Generating session summary...`);

    try {
      const summary = await generateSummary(sessionData, modelId, claudePath);

      if (summary) {
        // Use session end time (last event timestamp)
        const lastEvent = sessionData.allMessages[sessionData.allMessages.length - 1];
        const endTime = new Date(lastEvent.timestamp);

        const summaryResult = db.storeHistoricalSummary(
          sessionId,  // Use original session ID
          sessionData.project,
          summary,
          endTime,
          sessionData.userMessages.length,
          0
        );

        // Sync to Chroma if enabled
        if (chromaSync) {
          try {
            await chromaSync.syncSummary(
              summaryResult.id,
              sessionId,  // Use original session ID
              sessionData.project,
              summary,
              sessionData.userMessages.length,
              summaryResult.createdAtEpoch,
              0  // discoveryTokens
            );
          } catch (error: any) {
            console.error(`    ⚠️  Chroma sync failed for summary #${summaryResult.id}: ${error.message}`);
            // Continue even if Chroma sync fails
          }
        }

        stats.summary = true;
        console.log(`  ✓ Generated and stored session summary`);
      }
    } catch (error: any) {
      console.error(`  ❌ Failed to generate summary:`, error.message);
      console.error(`     Error details:`, error);
    }
  }

  // Mark session as completed
  db.markSessionCompleted(sessionDbId);

  return stats;
}

/**
 * Process a single project
 */
async function processProject(
  projectDir: string,
  db: SessionStore,
  modelId: string,
  claudePath: string,
  maxSessions: number | null,
  dryRun: boolean,
  syncToChroma: boolean = true
): Promise<{ sessions: number; prompts: number; observations: number; summaries: number }> {
  const projectName = basename(projectDir);
  console.log(`\n${'='.repeat(80)}`);
  console.log(`Processing: ${projectName}`);
  console.log(`${'='.repeat(80)}`);

  const files = readdirSync(projectDir).filter(f => f.endsWith('.jsonl'));
  console.log(`Found ${files.length} transcript file(s)`);

  // Process transcripts incrementally to avoid memory exhaustion
  // (thedotmack has 303 files - can't load all into memory at once)
  const sessions = new Map<string, SessionData>();

  for (const filename of files) {
    const filepath = join(projectDir, filename);
    const events = parseTranscript(filepath);

    // Group events from this file by session
    const fileSessions = groupBySession(events);

    // Merge with existing sessions (events from same session across multiple files)
    for (const [sessionId, fileSession] of fileSessions) {
      if (sessions.has(sessionId)) {
        // Merge into existing session
        const existing = sessions.get(sessionId)!;
        existing.userMessages.push(...fileSession.userMessages);
        existing.toolEvents.push(...fileSession.toolEvents);
        existing.allMessages.push(...fileSession.allMessages);
        existing.assistantResponses.push(...fileSession.assistantResponses);

        // Use earliest start time
        if (fileSession.startTime < existing.startTime) {
          existing.startTime = fileSession.startTime;
        }
      } else {
        // New session
        sessions.set(sessionId, fileSession);
      }
    }
  }

  // Sort messages within each session by timestamp
  for (const session of sessions.values()) {
    session.allMessages.sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());
    session.userMessages.sort((a, b) => a.timestamp.getTime() - b.timestamp.getTime());
    session.toolEvents.sort((a, b) => a.timestamp.getTime() - b.timestamp.getTime());
  }

  console.log(`Found ${sessions.size} session(s)`);

  // Limit sessions if requested
  const sessionsToProcess = maxSessions
    ? Array.from(sessions.values()).slice(0, maxSessions)
    : Array.from(sessions.values());

  const stats = {
    sessions: 0,
    prompts: 0,
    observations: 0,
    summaries: 0
  };

  // Process each session
  for (const sessionData of sessionsToProcess) {
    console.log(`\n  Session: ${sessionData.sessionId.substring(0, 8)}...`);
    console.log(`  Started: ${sessionData.startTime.toISOString()}`);
    console.log(`  Messages: ${sessionData.userMessages.length} user, ${sessionData.toolEvents.length} tools`);

    const sessionStats = await replaySession(sessionData, db, modelId, claudePath, dryRun, syncToChroma);

    stats.sessions++;
    stats.prompts += sessionStats.prompts;
    stats.observations += sessionStats.observations;
    if (sessionStats.summary) stats.summaries++;
  }

  return stats;
}

/**
 * Main function
 */
async function main() {
  const args = process.argv.slice(2);

  // Parse arguments
  const dryRun = args.includes('--dry-run');
  const isAllMode = args.includes('--all');
  const isSingleSession = args.includes('--session');
  const noChroma = args.includes('--no-chroma');
  const maxSessionsIdx = args.indexOf('--max-sessions');
  const maxSessions = maxSessionsIdx !== -1 && args[maxSessionsIdx + 1]
    ? parseInt(args[maxSessionsIdx + 1])
    : null;

  if (args.length === 0 || args.includes('-h') || args.includes('--help')) {
    console.log(`
Replay History - Comprehensive historical import into claude-mem

Usage:
  bun src/bin/replay-history.ts <project-dir>          Replay single project
  bun src/bin/replay-history.ts --all                  Replay all projects
  bun src/bin/replay-history.ts --all --dry-run        Preview without importing
  bun src/bin/replay-history.ts --all --max-sessions 5 Limit to 5 sessions
  bun src/bin/replay-history.ts --all --no-chroma      Skip Chroma vector sync
  bun src/bin/replay-history.ts --session <id> <dir>   Replay single session

What gets imported:
  ✓ Session records (with historical start times)
  ✓ User prompts (all your messages, searchable)
  ✓ Observations (generated from tool usage via SDK)
  ✓ Session summaries (generated via SDK)
  ✓ Chroma vector embeddings (for semantic search)

Examples:
  # Replay one project
  npx tsx src/bin/replay-history.ts ~/.claude/projects/-Users-...-myproject

  # Preview what would be imported from all projects
  npx tsx src/bin/replay-history.ts --all --dry-run

  # Import first 10 sessions from all projects
  npx tsx src/bin/replay-history.ts --all --max-sessions 10

Note:
  - This can take a while (SDK generates observations/summaries for each session)
  - Duplicate sessions are automatically skipped
  - Results appear in chronological order in claude-mem viewer
`);
    process.exit(0);
  }

  console.log('Starting historical replay...\n');

  if (dryRun) {
    console.log('⚠️  DRY RUN MODE - No data will be imported\n');
  }

  // Load settings
  const settings = SettingsDefaultsManager.loadFromFile(USER_SETTINGS_PATH);
  const modelId = settings.CLAUDE_MEM_MODEL || 'claude-sonnet-4-5';
  const claudePath = findClaudeExecutable();

  console.log(`Using model: ${modelId}`);
  console.log(`Claude path: ${claudePath}`);
  console.log(`Chroma sync: ${noChroma ? '❌ Disabled' : '✅ Enabled'}\n`);

  // Open database
  const db = new SessionStore();

  const projectsDir = join(homedir(), '.claude', 'projects');
  let projectDirs: string[] = [];

  if (isSingleSession) {
    // TODO: Implement single session replay
    console.error('❌ Single session replay not yet implemented');
    process.exit(1);
  } else if (isAllMode) {
    // Process all projects
    if (!existsSync(projectsDir)) {
      console.error(`❌ Projects directory not found: ${projectsDir}`);
      process.exit(1);
    }

    const items = readdirSync(projectsDir);
    for (const item of items) {
      if (item.startsWith('.') || item.endsWith('.zip')) continue;
      const fullPath = join(projectsDir, item);
      if (existsSync(fullPath) && readdirSync(fullPath).some(f => f.endsWith('.jsonl'))) {
        projectDirs.push(fullPath);
      }
    }

    projectDirs.sort();
    console.log(`Found ${projectDirs.length} project(s) with transcripts\n`);
  } else {
    // Process single project
    const projectDir = args[0]?.startsWith('~')
      ? args[0].replace('~', homedir())
      : args[0];

    if (!projectDir) {
      console.error('❌ No project directory specified');
      process.exit(1);
    }

    if (!existsSync(projectDir)) {
      console.error(`❌ Project directory not found: ${projectDir}`);
      process.exit(1);
    }

    projectDirs = [projectDir];
  }

  // Process all projects
  const grandStats = {
    sessions: 0,
    prompts: 0,
    observations: 0,
    summaries: 0
  };

  for (const projectDir of projectDirs) {
    const stats = await processProject(projectDir, db, modelId, claudePath, maxSessions, dryRun, !noChroma);
    grandStats.sessions += stats.sessions;
    grandStats.prompts += stats.prompts;
    grandStats.observations += stats.observations;
    grandStats.summaries += stats.summaries;
  }

  db.close();

  // Summary
  console.log(`\n${'='.repeat(80)}`);
  console.log('Replay Complete!');
  console.log('='.repeat(80));
  console.log(`Sessions imported: ${grandStats.sessions}`);
  console.log(`User prompts stored: ${grandStats.prompts}`);
  console.log(`Observations generated: ${grandStats.observations}`);
  console.log(`Summaries generated: ${grandStats.summaries}`);
  console.log('='.repeat(80));

  if (!dryRun) {
    console.log('\n✓ All history imported with original timestamps');
    console.log('  View at: http://localhost:37777');
    console.log('  Search: Use mem-search skill');
  }
}

// Run if executed directly
if (import.meta.url === `file://${process.argv[1]}`) {
  main().catch(err => {
    console.error('\n❌ Fatal error:', err);
    process.exit(1);
  });
}

